targets.expr:
(
      volume_read_data{cluster=~"$Cluster",datacenter=~"$Datacenter",node=~"$Node"}
    +
      volume_write_data{cluster=~"$Cluster",datacenter=~"$Datacenter",node=~"$Node"}
  )
and
  topk(
    $TopResources,
    (
        avg_over_time(
          volume_read_data{cluster=~"$Cluster",datacenter=~"$Datacenter",node=~"$Node"}[3h] @ end()
        )
      +
        avg_over_time(
          volume_write_data{cluster=~"$Cluster",datacenter=~"$Datacenter",node=~"$Node"}[3h] @ end()
        )
    )
  )

(
      nic_rx_bytes{cluster=~"$Cluster",datacenter=~"$Datacenter",node=~"$Node"}
    +
      nic_tx_bytes{cluster=~"$Cluster",datacenter=~"$Datacenter",node=~"$Node"}
  )
and on (datacenter, cluster, nic, node)
  topk(
    $TopResources,
    (
        avg_over_time(nic_rx_bytes{cluster=~"$Cluster",datacenter=~"$Datacenter",node=~"$Node"}[3h])
      +
        avg_over_time(nic_tx_bytes{cluster=~"$Cluster",datacenter=~"$Datacenter",node=~"$Node"}[3h])
    )
  )

(
          fcp_read_data{cluster=~"$Cluster",datacenter=~"$Datacenter",node=~"$Node"}
        +
          fcp_write_data{cluster=~"$Cluster",datacenter=~"$Datacenter",node=~"$Node"}
      +
        fcp_nvmf_read_data{cluster=~"$Cluster",datacenter=~"$Datacenter",node=~"$Node"}
    +
      fcp_nvmf_write_data{cluster=~"$Cluster",datacenter=~"$Datacenter",node=~"$Node"}
  )
and on (datacenter, cluster, port, node)
  topk(
    $TopResources,
    (
            avg_over_time(fcp_read_data{cluster=~"$Cluster",datacenter=~"$Datacenter",node=~"$Node"}[3h])
          +
            avg_over_time(fcp_write_data{cluster=~"$Cluster",datacenter=~"$Datacenter",node=~"$Node"}[3h])
        +
          avg_over_time(fcp_nvmf_read_data{cluster=~"$Cluster",datacenter=~"$Datacenter",node=~"$Node"}[3h])
      +
        avg_over_time(fcp_nvmf_write_data{cluster=~"$Cluster",datacenter=~"$Datacenter",node=~"$Node"}[3h])
    )
  )
